// OpenCL sparse-voxel-octree renderer.
// Default: real-time window with mouse-look. --bench: headless benchmark + BMP.
#include "octree.hpp"
#include "scene.hpp"
#include "level.hpp"
#include "world_file.hpp"
#include "dream.hpp"
#include <filesystem>
#include "world.hpp"
#include "renderer.hpp"
#if OCTREE_VIEWER
  #include "viewer.hpp"
#endif

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "kernel_source.hpp"   // generated by CMake from kernels/octree.cl

using Clock = std::chrono::steady_clock;
static double msSince(Clock::time_point t) {
    return std::chrono::duration<double, std::milli>(Clock::now() - t).count();
}

struct Options {
    int depth = 7, width = 1280, height = 720, frames = 30, device = -1;
    float angleDeg = 35.0f, scale = 1.0f;
    bool cpu = false, bench = false, vsync = false, fly = false, keyLog = false, fullscreen = false;
    RenderSettings settings;
    std::string out = "render.bmp", kernelFile, scene = "flat";
    std::string world = "worlds/default.world";   // world file (levels): loaded if it exists, Ctrl+S saves it
    bool sceneGiven = false, worldGiven = false;
};

static void usage() {
    std::puts(
        "usage: octree_render [options]\n"
        "  --world FILE     world file (all levels) to load if it exists and to save to with Ctrl+S\n"
        "                   (default worlds/default.world; loaded unless --scene is given)\n"
        "  --scene NAME     start a new world from a scene (default flat; see the list below)\n"
        "  --depth N        octree depth, 1..16 (default 7 = 128^3 voxels; +1 halves voxel size)\n"
        "  --size WxH       window / image size (default 1280x720)\n"
        "  --scale S        render at S x window resolution, e.g. 0.5 (default 1)\n"
        "  --vsync          cap the frame rate to the display\n"
        "  --fly            start in free-fly (noclip) mode instead of walking\n"
        "  --keylog         print every key press to the console (diagnostics)\n"
        "  --fullscreen     start in full screen (F11 toggles)\n"
        "  --lens L         perspective | fisheye (default perspective)\n"
        "  --fov DEG        field of view: fisheye horizontal (default 200),\n"
        "                   perspective vertical (default 70)\n"
        "  --mode M         shaded | normals | steps | depth\n"
        "  --lod P          stop descending below P pixels, 0 = off (default 1)\n"
        "  --no-shadows     disable shadow rays\n"
        "  --no-filter      flat voxel colours (no bilinear filtering)\n"
        "  --texels N       N x N nearest-sampled texels per voxel face, 0 = smooth (default 4)\n"
        "  --cpu            run the same kernel on the CPU instead of OpenCL\n"
        "  --device I       OpenCL device index (see the list printed at start)\n"
        "  --kernel FILE    load kernel source from FILE instead of the built-in copy\n"
        "  --bench          no window: time --frames orbiting frames, save --out\n"
        "  --frames N       frames for --bench (default 30)\n"
        "  --angle DEG      camera orbit angle of the saved --bench frame (default 35)\n"
        "  --out FILE.bmp   --bench output image (default render.bmp)");
    std::puts("scenes:");
    for (const Scene* sc : allScenes()) std::printf("  %-8s %s\n", sc->name, sc->description);
}

static bool parseArgs(int argc, char** argv, Options& o) {
    float fovArg = 0.0f;
    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        auto next = [&]() -> const char* {
            if (i + 1 >= argc) { std::fprintf(stderr, "missing value for %s\n", a.c_str()); std::exit(1); }
            return argv[++i];
        };
        if (a == "--depth") o.depth = std::atoi(next());
        else if (a == "--scene") { o.scene = next(); o.sceneGiven = true; }
        else if (a == "--world") { o.world = next(); o.worldGiven = true; }
        else if (a == "--size") { if (std::sscanf(next(), "%dx%d", &o.width, &o.height) != 2) return false; }
        else if (a == "--scale") o.scale = (float)std::atof(next());
        else if (a == "--vsync") o.vsync = true;
        else if (a == "--fly") o.fly = true;
        else if (a == "--keylog") o.keyLog = true;
        else if (a == "--fullscreen") o.fullscreen = true;
        else if (a == "--frames") o.frames = std::max(1, std::atoi(next()));
        else if (a == "--mode") {
            std::string m = next();
            if (m == "shaded") o.settings.mode = RENDER_SHADED;
            else if (m == "normals") o.settings.mode = RENDER_NORMALS;
            else if (m == "steps") o.settings.mode = RENDER_STEPS;
            else if (m == "depth") o.settings.mode = RENDER_DEPTH;
            else return false;
        }
        else if (a == "--lens") {
            std::string l = next();
            if (l == "fisheye") o.settings.projection = PROJ_FISHEYE_HOST;
            else if (l == "perspective") o.settings.projection = PROJ_PERSPECTIVE_HOST;
            else return false;
        }
        else if (a == "--fov") fovArg = (float)std::atof(next());
        else if (a == "--lod") o.settings.lodPixels = (float)std::atof(next());
        else if (a == "--no-shadows") o.settings.shadows = false;
        else if (a == "--no-filter") o.settings.filter = false;
        else if (a == "--texels") o.settings.texels = std::clamp(std::atoi(next()), 0, 64);
        else if (a == "--angle") o.angleDeg = (float)std::atof(next());
        else if (a == "--cpu") o.cpu = true;
        else if (a == "--device") o.device = std::atoi(next());
        else if (a == "--kernel") o.kernelFile = next();
        else if (a == "--bench") o.bench = true;
        else if (a == "--out") o.out = next();
        else if (a == "-h" || a == "--help") { usage(); std::exit(0); }
        else { std::fprintf(stderr, "unknown option %s\n", a.c_str()); return false; }
    }
    if (fovArg > 0.0f) {   // applies to whichever lens was chosen
        if (o.settings.projection == PROJ_FISHEYE_HOST) o.settings.fisheyeFovDeg = std::min(fovArg, 360.0f);
        else o.settings.fovDeg = std::min(fovArg, 170.0f);
    }
    o.depth = std::clamp(o.depth, 1, 16);
    return o.width > 0 && o.height > 0;
}

static bool writeBmp(const std::string& path, const std::vector<uint32_t>& px, int w, int h) {
    std::ofstream f(path, std::ios::binary);
    if (!f) return false;
    int rowBytes = (w * 3 + 3) & ~3;
    uint32_t dataSize = (uint32_t)(rowBytes * h), fileSize = 54 + dataSize;
    uint8_t hdr[54] = {'B', 'M'};
    auto put32 = [&](int off, uint32_t v) { for (int i = 0; i < 4; ++i) hdr[off + i] = (uint8_t)(v >> (8 * i)); };
    put32(2, fileSize); put32(10, 54); put32(14, 40); put32(18, (uint32_t)w); put32(22, (uint32_t)h);
    hdr[26] = 1; hdr[28] = 24; put32(34, dataSize);
    f.write((const char*)hdr, 54);
    std::vector<uint8_t> row(rowBytes, 0);
    for (int y = h - 1; y >= 0; --y) {
        for (int x = 0; x < w; ++x) {
            uint32_t c = px[(size_t)y * w + x];
            row[x * 3 + 0] = (uint8_t)(c >> 16); row[x * 3 + 1] = (uint8_t)(c >> 8); row[x * 3 + 2] = (uint8_t)c;
        }
        f.write((const char*)row.data(), rowBytes);
    }
    return true;
}

static int runBench(Renderer& r, const Options& o) {
    std::vector<uint32_t> image((size_t)o.width * o.height);
    auto frameParams = [&](int f) {   // camera orbits; the last frame is at --angle
        float a = o.angleDeg - (o.frames - 1 - f) * 3.0f;
        return makeParams(defaultCamera(a), o.width, o.height, o.settings);
    };
    if (!r.render(frameParams(0), image.data())) return 1;   // warm-up
    double total = 0, best = 1e30;
    for (int f = 0; f < o.frames; ++f) {
        Params p = frameParams(f);
        auto t0 = Clock::now();
        if (!r.render(p, image.data())) return 1;
        double ms = msSince(t0);
        total += ms; best = std::min(best, ms);
    }
    double avg = total / o.frames;
    std::printf("%s: %d frames at %dx%d, avg %.2f ms (%.1f fps), best %.2f ms (includes readback)\n",
                r.name().c_str(), o.frames, o.width, o.height, avg, 1000.0 / avg, best);
    if (!writeBmp(o.out, image, o.width, o.height)) {
        std::fprintf(stderr, "failed to write %s\n", o.out.c_str());
        return 1;
    }
    std::printf("Wrote %s\n", o.out.c_str());
    return 0;
}

int main(int argc, char** argv) {
    std::setvbuf(stdout, nullptr, _IONBF, 0);
    Options o;
    if (!parseArgs(argc, argv, o)) { usage(); return 1; }

    std::string src(reinterpret_cast<const char*>(kOctreeKernelSource), sizeof(kOctreeKernelSource));
    if (!o.kernelFile.empty()) {
        std::ifstream f(o.kernelFile);
        if (!f) { std::fprintf(stderr, "cannot read %s\n", o.kernelFile.c_str()); return 1; }
        std::stringstream ss; ss << f.rdbuf(); src = ss.str();
    }

    const Scene* scene = findScene(o.scene);
    if (!scene) { std::fprintf(stderr, "unknown scene '%s'\n", o.scene.c_str()); usage(); return 1; }
    auto t0 = Clock::now();
    // The game's levels (one for now, made from the scene). Each level owns its
    // editable world; the renderer and physics use the current level's octree.
    LevelSet levels;
    std::error_code fsErr;
    const bool fromFile = (o.worldGiven || !o.sceneGiven) && std::filesystem::exists(o.world, fsErr);
    if (fromFile) {
        std::string err;
        if (!loadWorld(o.world, levels, err)) { std::fprintf(stderr, "%s\n", err.c_str()); return 1; }
        std::printf("World '%s': %d level(s) loaded\n", o.world.c_str(), levels.count());
        o.depth = levels.baseLevel;
    } else {
        levels.baseLevel = o.depth;
        levels.add(scene->name, buildOctree(*scene, o.depth));
        std::printf("New world from scene '%s' (Ctrl+S saves it to %s)\n", scene->name, o.world.c_str());
    }
    if (!levels.dream) levels.dream = Dream::create(levels.baseLevel);   // older world files have none
    linkDream(levels);                                                   // cage voxels point into the dream
    Level& level = levels.current();
    const Octree& oct = level.world.octree();
    std::printf("Level '%s' - Octree: depth %d (%d^3), %zu nodes, %.1f MB, ready in %.0f ms\n",
                level.name.c_str(), o.depth, 1 << o.depth, oct.nodeCount(),
                (oct.nodes.size() + oct.colors.size()) * 4 / 1048576.0, msSince(t0));

    std::unique_ptr<Renderer> renderer;
    if (!o.cpu) {
        renderer = createOpenCLRenderer(oct, src, o.device);
        if (!renderer) std::fprintf(stderr, "Falling back to the CPU renderer.\n");
    }
    if (!renderer) {
        renderer = createCpuRenderer(oct);
        if (!o.bench && o.scale >= 1.0f) {
            o.scale = 0.5f;   // keep the CPU path usable interactively
            std::printf("CPU renderer: using --scale 0.5 for the window ([ and ] to change).\n");
        }
    }
    std::printf("Renderer: %s\n", renderer->name().c_str());

#if OCTREE_VIEWER
    if (!o.bench) {
        ViewerOptions v;
        v.width = o.width; v.height = o.height;
        v.renderScale = o.scale; v.vsync = o.vsync; v.startFlying = o.fly; v.keyLog = o.keyLog;
        v.fullscreen = o.fullscreen;
        v.buildLevel = levels.baseLevel;   // default block = one voxel of the world
        v.worldPath = o.world;
        v.settings = o.settings;
        return runViewer(*renderer, levels, v);
    }
#else
    if (!o.bench) std::printf("Built without the viewer (OCTREE_VIEWER=OFF): running --bench.\n");
#endif
    return runBench(*renderer, o);
}
